class Solution { bool stretchy(string& target,string& word){int i=0,j=0;while(i<(int)target.size()&&j<(int)word.size()){if(target[i]!=word[j])return false;int nextI=i+1,nextJ=j+1;while(nextI<(int)target.size()&&target[nextI]==target[i])++nextI;while(nextJ<(int)word.size()&&word[nextJ]==word[j])++nextJ;int a=nextI-i,b=nextJ-j;if(b>a||(a!=b&&a<3))return false;i=nextI;j=nextJ;}return i==(int)target.size()&&j==(int)word.size();}public:int expressiveWords(string s,vector<string>& words){int answer=0;for(string& word:words)answer+=stretchy(s,word);return answer;} };
